-- Test data for NycprfPartnerRepositoryTest (H2 in Oracle mode).
-- Only the columns the partner query reads; AGE is a NUMBER and the dates carry a time part,
-- to pin down the type conversions the old MyBatis mapper did.

-- the Oracle function FN_TO_DATE (see H2OracleFunctions)
CREATE ALIAS IF NOT EXISTS FN_TO_DATE FOR "gov.ny.state.doh.bhae.nyehms.web.spring.repository.document.H2OracleFunctions.fnToDate";

CREATE TABLE STD_NYCPRF_PARTNER (
	PATIENT_ID VARCHAR2(50), NYCPRF_DOCUMENT_ID VARCHAR2(50), FNAME VARCHAR2(100), MNAME VARCHAR2(100), LNAME VARCHAR2(100),
	ALT_NAME VARCHAR2(100), ADDRESS VARCHAR2(200), CITY VARCHAR2(100), STATE VARCHAR2(10), ZIP VARCHAR2(10), PLUS4 VARCHAR2(10),
	HOME_PHONE VARCHAR2(20), CELL_PHONE VARCHAR2(20), PAGER VARCHAR2(20), EMAIL VARCHAR2(100), DOB_TEXT VARCHAR2(20), AGE NUMBER(5),
	CURRENT_GENDER VARCHAR2(10), ETHNICITY VARCHAR2(10), RACE_WHITE VARCHAR2(1), RACE_BLACK VARCHAR2(1), RACE_ASIAN VARCHAR2(1),
	RACE_INDIAN VARCHAR2(1), RACE_PACIFIC VARCHAR2(1), RACE_UNKNOWN VARCHAR2(1), RACE_OTHER VARCHAR2(1), RACE_OTHER_TEXT VARCHAR2(100),
	COMPLEXION_PARTNER VARCHAR2(20), HAIR_PARTNER VARCHAR2(20), HEIGHT VARCHAR2(10), WEIGHT VARCHAR2(10), PLACE_OF_EMPLOYMENT VARCHAR2(100),
	WORK_HOURS VARCHAR2(50), WORK_PHONE VARCHAR2(20), MARITAL_CODE VARCHAR2(10), PREGNANT VARCHAR2(1), SPOUSE VARCHAR2(1),
	DVSCREEN VARCHAR2(10), RISK_VIOLENCE VARCHAR2(10), PARTNER_ASSISTANCE_STATUS VARCHAR2(10), PARTNER_TEST_DATE_TEXT VARCHAR2(20),
	PARTNER_STATUS VARCHAR2(10), HDISP_DT DATE, CREATE_UID VARCHAR2(20), CREATE_DATE DATE, INFORMED_DATE DATE,
	HIGH_PRIORITY VARCHAR2(1), ELICITED_BY_PNAP VARCHAR2(1), ELICITED_BY_ACT VARCHAR2(1),
	RACE_CD VARCHAR2(100), PARTNRID VARCHAR2(100), BIRTH_SEX VARCHAR2(100), NOTIFIED_DATE VARCHAR2(100), ENTER_DATE VARCHAR2(100), EHARS_DIAG_DATE_TEXT VARCHAR2(100), CITYNO VARCHAR2(100), PRIORITY VARCHAR2(100), SOURCE VARCHAR2(100), PARTNERS VARCHAR2(100), REFERRAL VARCHAR2(100), DISEASE_1 VARCHAR2(100), DISEASE_2 VARCHAR2(100), CODE VARCHAR2(100), INTERVIEW VARCHAR2(100), INTERVIEW_TYPE VARCHAR2(100), REFERRAL_TYPE VARCHAR2(100), PRINTED VARCHAR2(100), NOTSEND VARCHAR2(100), UPDATED_DATE DATE, INDEX_CITYNO VARCHAR2(100), DISPO VARCHAR2(100), HIVDISPO_DATE_TEXT VARCHAR2(100)
);

CREATE TABLE RAW_NYCPRF_PARTNER (
	PATIENTID VARCHAR2(50), NYCPRF_DOCUMENT_ID NUMBER(12), PRTADDRESS VARCHAR2(200),
	CITYNO VARCHAR2(100), CODE VARCHAR2(100), DISEASE1 VARCHAR2(100), DISEASE2 VARCHAR2(100), HPRIORITY VARCHAR2(100), INDEXCITYNO VARCHAR2(100), INTERV VARCHAR2(100), NOTSEND VARCHAR2(100), P VARCHAR2(100), PARTNERID VARCHAR2(100), PRF_ELICITED VARCHAR2(100), PRF_HIVSTUS VARCHAR2(100), PRF_SPOUSE VARCHAR2(100), PRF_TSTDT VARCHAR2(100), PRIDTINF VARCHAR2(100), PRINTED VARCHAR2(100), PRIORITY VARCHAR2(100), PRTAGE VARCHAR2(100), PRTALIAS VARCHAR2(100), PRTASSISSTATUS VARCHAR2(100), PRTCITY VARCHAR2(100), PRTCOMPLEX VARCHAR2(100), PRTCPHONE VARCHAR2(100), PRTCURGENDER VARCHAR2(100), PRTDOB VARCHAR2(100), PRTDTHARSDX VARCHAR2(100), PRTDTNOFITIED VARCHAR2(100), PRTDVIOLENCEDONE VARCHAR2(100), PRTEMAIL VARCHAR2(100), PRTENTERDT VARCHAR2(100), PRTFNAME VARCHAR2(100), PRTHAIR VARCHAR2(100), PRTHEIWEI VARCHAR2(100), PRTHPHONE VARCHAR2(100), PRTHVDISPO VARCHAR2(100), PRTHVDISPODT VARCHAR2(100), PRTLNAME VARCHAR2(100), PRTMARITALSTUS VARCHAR2(100), PRTMI VARCHAR2(100), PRTPREGNANT VARCHAR2(100), PRTRACE VARCHAR2(100), PRTRSKOFDVIOLENCE VARCHAR2(100), PRTSEXBIRTH VARCHAR2(100), PRTSTATE VARCHAR2(100), PRTZIP VARCHAR2(100), REFERRAL VARCHAR2(100), SOURCE VARCHAR2(100), TYPEINTERV VARCHAR2(100), TYPEREF VARCHAR2(100), UPDATED VARCHAR2(100), WRKTEL VARCHAR2(100)
);

